import std.io

pub type AppError = Failed(String)

pub fn main() effect io -> Result<(), AppError> {
    let acc = 0
    for i in 0..3 { acc = acc + i }
    if acc == 3 { io.println("count-ok") } else { io.println("count-bad") }

    let c = 0
    for i in 0..5 {
        if i == 2 { continue }
        c = c + 1
    }
    if c == 4 { io.println("cont-ok") } else { io.println("cont-bad") }

    let b = 0
    for i in 0..5 {
        if i == 2 { break }
        b = b + 1
    }
    if b == 2 { io.println("break-ok") } else { io.println("break-bad") }

    let s = 0
    for i in 0..3 {
        i = i + 5
        s = s + i
    }
    if s == 18 { io.println("fresh-ok") } else { io.println("fresh-bad") }

    let hi = 3
    let t = 0
    for i in 0..hi {
        hi = 1
        t = t + 1
    }
    if t == 3 { io.println("bound-ok") } else { io.println("bound-bad") }

    return Ok(())
}
